def choose_move(observation):
    own_pos = observation.get('own', {}).get('position', (0, 0))
    resource_positions = observation.get('resources', [])
    opponents = observation.get('opponents', [])
    territory_control_points = observation.get('territory_control_points', [])
    grid_bounds = observation.get('grid_bounds', (0, 0))

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def clamp(n, min_n, max_n):
        return max(min_n, min(n, max_n))

    own_x, own_y = own_pos
    max_x, max_y = grid_bounds

    # Helper to find the closest target position within bounds
    def closest_target(current, targets):
        valid_targets = [pos for pos in targets if 0 <= pos[0] <= max_x and 0 <= pos[1] <= max_y]
        if not valid_targets:
            return None
        return min(valid_targets, key=lambda pos: dist(current, pos))

    # Strategy: prioritize resources, then opponents, then territory control
    for target_list in [resource_positions, 
                        [op.get('position') for op in opponents if 'position' in op], 
                        territory_control_points]:
        target = closest_target(own_pos, target_list)
        if target:
            tx, ty = target
            dx = (tx - own_x)
            dy = (ty - own_y)
            dx = (dx > 0) - (dx < 0)
            dy = (dy > 0) - (dy < 0)
            # Ensure moving stays within grid bounds
            new_x = clamp(own_x + dx, 0, max_x)
            new_y = clamp(own_y + dy, 0, max_y)
            # Adjust dx, dy if movement would go out of bounds
            if new_x == own_x:
                dx = 0
            if new_y == own_y:
                dy = 0
            return [dx, dy]

    # No targets, stay in place
    return [0, 0]

